<script setup lang="ts">
// Dictionary Management (generated by engineering-platform frontend-enterprise-management asset)
// Master-detail: dictionary types (left) + items (right).
// Type create/update/enable/disable; Item create/update/enable/disable/sort.
// Stable codes: type.code and item.value are not editable after creation.
import { onMounted, reactive, ref } from 'vue';
import PageHeader from '../../components/PageHeader.vue';
import PageContainer from '../../components/PageContainer.vue';
import StatusTag from '../../components/StatusTag.vue';
import ConfirmAction from '../../components/ConfirmAction.vue';
import PermissionButton from '../../permission/PermissionButton.vue';
import FormDrawer from '../../components/FormDrawer.vue';
import AppForm from '../../components/AppForm.vue';
import { dictionaryApi } from '../../api/enterprise';
import type { DictionaryType, DictionaryItem, EntityId } from '../../types/enterprise';
import { errorMessage, notifySuccess, toastSuccess } from '../../utils/feedback';

const types = ref<DictionaryType[]>([]);
const typesError = ref<string | null>(null);
const selectedType = ref<DictionaryType | null>(null);
const items = ref<DictionaryItem[]>([]);
const itemsLoading = ref(false);
const itemsError = ref<string | null>(null);

// type form (drawer)
const typeDrawer = ref(false);
const typeEditing = ref(false);
const typeSubmitting = ref(false);
const typeFormError = ref<string | null>(null);
const typeForm = reactive({ code: '', name: '', description: '' });

// item form (drawer)
const itemDrawer = ref(false);
const itemEditing = ref<DictionaryItem | null>(null);
const itemSubmitting = ref(false);
const itemFormError = ref<string | null>(null);
const itemForm = reactive({ value: '', label: '', sort: 0, description: '' });

async function loadTypes(): Promise<void> {
  typesError.value = null;
  try {
    types.value = await dictionaryApi.types();
  } catch (e) {
    typesError.value = errorMessage(e);
  }
}

async function selectType(t: DictionaryType): Promise<void> {
  selectedType.value = t;
  await loadItems(t.id);
}

async function loadItems(typeId: EntityId): Promise<void> {
  itemsLoading.value = true;
  itemsError.value = null;
  try {
    items.value = await dictionaryApi.itemsOfType(typeId);
  } catch (e) {
    itemsError.value = errorMessage(e);
  } finally {
    itemsLoading.value = false;
  }
}

function openCreateType(): void {
  typeEditing.value = false;
  typeFormError.value = null;
  Object.assign(typeForm, { code: '', name: '', description: '' });
  typeDrawer.value = true;
}

function openEditType(t: DictionaryType): void {
  typeEditing.value = true;
  typeFormError.value = null;
  Object.assign(typeForm, { code: t.code, name: t.name, description: t.description ?? '' });
  typeDrawer.value = true;
}

async function submitType(): Promise<void> {
  typeSubmitting.value = true;
  typeFormError.value = null;
  try {
    if (typeEditing.value && selectedType.value) {
      await dictionaryApi.updateType(selectedType.value.id, {
        name: typeForm.name,
        description: typeForm.description,
      });
      notifySuccess('Dictionary type updated');
    } else {
      const created = await dictionaryApi.createType({
        code: typeForm.code,
        name: typeForm.name,
        description: typeForm.description,
      });
      notifySuccess('Dictionary type created');
      await loadTypes();
      await selectType(created);
    }
    typeDrawer.value = false;
    await loadTypes();
  } catch (e) {
    typeFormError.value = errorMessage(e);
  } finally {
    typeSubmitting.value = false;
  }
}

async function setTypeEnabled(t: DictionaryType, enabled: boolean): Promise<void> {
  try {
    if (enabled) {
      await dictionaryApi.enableType(t.id);
      toastSuccess('Type enabled');
    } else {
      await dictionaryApi.disableType(t.id);
      toastSuccess('Type disabled');
    }
    await loadTypes();
    if (selectedType.value?.id === t.id) {
      selectedType.value = { ...t, enabled };
    }
  } catch (e) {
    toastSuccess(errorMessage(e));
  }
}

function openCreateItem(): void {
  if (!selectedType.value) {
    return;
  }
  itemEditing.value = null;
  itemFormError.value = null;
  Object.assign(itemForm, { value: '', label: '', sort: 0, description: '' });
  itemDrawer.value = true;
}

function openEditItem(item: DictionaryItem): void {
  itemEditing.value = item;
  itemFormError.value = null;
  Object.assign(itemForm, { value: item.value, label: item.label, sort: item.sort, description: item.description ?? '' });
  itemDrawer.value = true;
}

async function submitItem(): Promise<void> {
  if (!selectedType.value) {
    return;
  }
  itemSubmitting.value = true;
  itemFormError.value = null;
  try {
    if (itemEditing.value) {
      await dictionaryApi.updateItem(itemEditing.value.id, {
        label: itemForm.label,
        sort: itemForm.sort,
        description: itemForm.description,
      });
      notifySuccess('Dictionary item updated');
    } else {
      await dictionaryApi.createItem(selectedType.value.id, {
        value: itemForm.value,
        label: itemForm.label,
        sort: itemForm.sort,
        description: itemForm.description,
      });
      notifySuccess('Dictionary item created');
    }
    itemDrawer.value = false;
    await loadItems(selectedType.value.id);
  } catch (e) {
    itemFormError.value = errorMessage(e);
  } finally {
    itemSubmitting.value = false;
  }
}

async function setItemEnabled(item: DictionaryItem, enabled: boolean): Promise<void> {
  try {
    if (enabled) {
      await dictionaryApi.enableItem(item.id);
      toastSuccess('Item enabled');
    } else {
      await dictionaryApi.disableItem(item.id);
      toastSuccess('Item disabled');
    }
    if (selectedType.value) {
      await loadItems(selectedType.value.id);
    }
  } catch (e) {
    toastSuccess(errorMessage(e));
  }
}

onMounted(loadTypes);
</script>

<template>
  <PageContainer full-width>
    <PageHeader title="Dictionary Management" description="Business reference data. Codes and values are stable — they are not editable after creation.">
      <template #actions>
        <PermissionButton permission="system:dictionary:create" type="primary" data-testid="create-type" @click="openCreateType">
          Create Type
        </PermissionButton>
      </template>
    </PageHeader>

    <div class="dictionary-layout" data-testid="dictionary-layout">
      <aside class="dictionary-types-pane">
        <div v-if="typesError" class="pane-error">
          <span>{{ typesError }}</span>
          <el-button size="small" @click="loadTypes">Retry</el-button>
        </div>
        <el-table
          v-else
          :data="types"
          highlight-current-row
          :row-key="(row: DictionaryType) => row.id"
          data-testid="dictionary-types"
          @current-change="(row: DictionaryType | null) => row && selectType(row)"
        >
          <el-table-column prop="name" label="Type" min-width="140">
            <template #default="{ row }">
              <div class="type-name">{{ row.name }}</div>
              <div class="type-code">{{ row.code }}</div>
            </template>
          </el-table-column>
          <el-table-column label="Status" width="90">
            <template #default="{ row }">
              <StatusTag :enabled="row.enabled" />
            </template>
          </el-table-column>
        </el-table>
      </aside>

      <main class="dictionary-items-pane">
        <el-empty v-if="!selectedType" description="Select a dictionary type on the left" />
        <div v-else>
          <div class="items-header">
            <div>
              <h3 class="items-title">{{ selectedType.name }}</h3>
              <span class="items-subtitle">{{ selectedType.code }} — {{ items.length }} items</span>
            </div>
            <div class="items-header-actions">
              <PermissionButton permission="system:dictionary:update" data-testid="edit-type" @click="openEditType(selectedType)">
                Edit type
              </PermissionButton>
              <ConfirmAction
                v-if="selectedType.enabled"
                title="Disable this type?"
                message="Existing references stay valid, but the type is no longer available for selection."
                data-testid="disable-type-confirm"
              >
                <PermissionButton permission="system:dictionary:disable" type="danger" plain>Disable type</PermissionButton>
              </ConfirmAction>
              <PermissionButton
                v-else
                permission="system:dictionary:update"
                data-testid="enable-type"
                @click="setTypeEnabled(selectedType, true)"
              >
                Enable type
              </PermissionButton>
              <PermissionButton permission="system:dictionary:create" type="primary" data-testid="create-item" @click="openCreateItem">
                Create Item
              </PermissionButton>
            </div>
          </div>

          <el-alert v-if="itemsError" type="error" :title="itemsError" :closable="false" class="items-error" />
          <el-table v-else v-loading="itemsLoading" :data="items" data-testid="dictionary-items">
            <el-table-column prop="value" label="Value" min-width="120" />
            <el-table-column prop="label" label="Label" min-width="140" />
            <el-table-column prop="sort" label="Sort" width="80" />
            <el-table-column label="Status" width="100">
              <template #default="{ row }">
                <StatusTag :enabled="row.enabled" />
              </template>
            </el-table-column>
            <el-table-column label="Actions" width="180" fixed="right">
              <template #default="{ row }">
                <el-button size="small" type="primary" link data-testid="edit-item" @click="openEditItem(row)">Edit</el-button>
                <ConfirmAction
                  v-if="row.enabled"
                  :title="'Disable item ' + (row.label) + '?'"
                  data-testid="disable-item-confirm"
                >
                  <el-button size="small" type="danger" link>Disable</el-button>
                </ConfirmAction>
                <el-button v-else size="small" link data-testid="enable-item" @click="setItemEnabled(row, true)">Enable</el-button>
              </template>
            </el-table-column>
          </el-table>
        </div>
      </main>
    </div>

    <FormDrawer v-model="typeDrawer" :title="typeEditing ? 'Edit Type' : 'Create Type'" width="460px">
      <AppForm
        :model="typeForm as unknown as Record<string, unknown>"
        :submitting="typeSubmitting"
        :error="typeFormError"
        :submit-text="typeEditing ? 'Save' : 'Create'"
        compact
        @submit="submitType"
        @cancel="typeDrawer = false"
      >
        <el-form-item label="Code" :rules="[{ required: true, message: 'Code is required' }]">
          <el-input v-model="typeForm.code" :disabled="typeEditing" placeholder="e.g. product_status" data-testid="type-form-code" />
          <div v-if="typeEditing" class="form-hint">Code is immutable once created.</div>
        </el-form-item>
        <el-form-item label="Name">
          <el-input v-model="typeForm.name" data-testid="type-form-name" />
        </el-form-item>
        <el-form-item label="Description">
          <el-input v-model="typeForm.description" type="textarea" data-testid="type-form-description" />
        </el-form-item>
      </AppForm>
    </FormDrawer>

    <FormDrawer v-model="itemDrawer" :title="itemEditing ? 'Edit Item' : 'Create Item'" width="460px">
      <AppForm
        :model="itemForm as unknown as Record<string, unknown>"
        :submitting="itemSubmitting"
        :error="itemFormError"
        :submit-text="itemEditing ? 'Save' : 'Create'"
        compact
        @submit="submitItem"
        @cancel="itemDrawer = false"
      >
        <el-form-item label="Value" :rules="[{ required: true, message: 'Value is required' }]">
          <el-input v-model="itemForm.value" :disabled="!!itemEditing" placeholder="e.g. DRAFT" data-testid="item-form-value" />
          <div v-if="itemEditing" class="form-hint">Value is immutable once created.</div>
        </el-form-item>
        <el-form-item label="Label">
          <el-input v-model="itemForm.label" data-testid="item-form-label" />
        </el-form-item>
        <el-form-item label="Sort">
          <el-input-number v-model="itemForm.sort" :min="0" data-testid="item-form-sort" />
        </el-form-item>
        <el-form-item label="Description">
          <el-input v-model="itemForm.description" type="textarea" data-testid="item-form-description" />
        </el-form-item>
      </AppForm>
    </FormDrawer>
  </PageContainer>
</template>

